import React, { useState } from "react";
import { useNavigate } from "react-router-dom";
import axios from "axios";

function BarberRegister() {
	const navigate = useNavigate();
	const [formData, setFormData] = useState({
		email: "",
		password: "",
		name: "",
		businessName: "",
		location: "",
		specialties: ["4a"],
	});
	const [loading, setLoading] = useState(false);
	const [error, setError] = useState("");

	const handleChange = (e) => {
		setFormData({
			...formData,
			[e.target.name]: e.target.value,
		});
	};

	const handleSpecialtyChange = (e) => {
		const value = e.target.value;
		if (e.target.checked) {
			setFormData({
				...formData,
				specialties: [...formData.specialties, value],
			});
		} else {
			setFormData({
				...formData,
				specialties: formData.specialties.filter((s) => s !== value),
			});
		}
	};

	const handleSubmit = async (e) => {
		e.preventDefault();
		setLoading(true);
		setError("");

		try {
			const response = await axios.post(
				"http://localhost:8000/api/auth/register-barber",
				formData
			);

			localStorage.setItem("token", response.data.token);
			localStorage.setItem("barber", JSON.stringify(response.data.barber));

			navigate("/barber/dashboard");
		} catch (err) {
			setError(err.response?.data?.error || "Registration failed");
		} finally {
			setLoading(false);
		}
	};

	const hairTypes = [
		"4a",
		"4b",
		"4c",
		"3a",
		"3b",
		"3c",
		"2a",
		"2b",
		"2c",
		"1a",
		"1b",
		"1c",
	];

	return (
		<div className="max-w-md mx-auto bg-white p-8 rounded-lg shadow-md">
			<h2 className="text-2xl font-bold text-center text-gray-800 mb-6">
				Register as Barber
			</h2>

			{error && (
				<div className="bg-red-100 border border-red-400 text-red-700 px-4 py-3 rounded mb-4">
					{error}
				</div>
			)}

			<form onSubmit={handleSubmit} className="space-y-4">
				<div>
					<label className="block text-gray-700 text-sm font-bold mb-2">
						Email
					</label>
					<input
						type="email"
						name="email"
						value={formData.email}
						onChange={handleChange}
						required
						className="w-full px-3 py-2 border border-gray-300 rounded focus:outline-none focus:border-blue-500"
					/>
				</div>

				<div>
					<label className="block text-gray-700 text-sm font-bold mb-2">
						Password
					</label>
					<input
						type="password"
						name="password"
						value={formData.password}
						onChange={handleChange}
						required
						className="w-full px-3 py-2 border border-gray-300 rounded focus:outline-none focus:border-blue-500"
					/>
				</div>

				<div>
					<label className="block text-gray-700 text-sm font-bold mb-2">
						Full Name
					</label>
					<input
						type="text"
						name="name"
						value={formData.name}
						onChange={handleChange}
						required
						className="w-full px-3 py-2 border border-gray-300 rounded focus:outline-none focus:border-blue-500"
					/>
				</div>

				<div>
					<label className="block text-gray-700 text-sm font-bold mb-2">
						Business Name
					</label>
					<input
						type="text"
						name="businessName"
						value={formData.businessName}
						onChange={handleChange}
						required
						className="w-full px-3 py-2 border border-gray-300 rounded focus:outline-none focus:border-blue-500"
					/>
				</div>

				<div>
					<label className="block text-gray-700 text-sm font-bold mb-2">
						Location
					</label>
					<input
						type="text"
						name="location"
						value={formData.location}
						onChange={handleChange}
						required
						placeholder="e.g., Brooklyn, NY"
						className="w-full px-3 py-2 border border-gray-300 rounded focus:outline-none focus:border-blue-500"
					/>
				</div>

				<div>
					<label className="block text-gray-700 text-sm font-bold mb-2">
						Hair Type Specialties
					</label>
					<div className="grid grid-cols-3 gap-2">
						{hairTypes.map((hairType) => (
							<label key={hairType} className="flex items-center">
								<input
									type="checkbox"
									value={hairType}
									checked={formData.specialties.includes(hairType)}
									onChange={handleSpecialtyChange}
									className="mr-2"
								/>
								{hairType}
							</label>
						))}
					</div>
				</div>

				<button
					type="submit"
					disabled={loading}
					className="w-full bg-green-600 text-white py-2 px-4 rounded hover:bg-green-700 disabled:opacity-50"
				>
					{loading ? "Creating Account..." : "Create Barber Account"}
				</button>
			</form>
		</div>
	);
}

export default BarberRegister;
